#!/usr/bin/env bash
set -u
G='\033[0;32m';R='\033[0;31m';C='\033[0;36m';W='\033[1;37m';Y='\033[1;33m';N='\033[0m'
banner(){ clear 2>/dev/null||true; echo -e "${C}╔══════════════════════════════════════════════════╗${N}"; echo -e "${C}║${W}                     APNELY                     ${C}║${N}"; echo -e "${C}║${W}                  CERTBOT / SSL                 ${C}║${N}"; echo -e "${C}║${W}              MADE BY ARNAV SHARMA             ${C}║${N}"; echo -e "${C}╚══════════════════════════════════════════════════╝${N}";echo;};ok(){ echo -e "${G}✓${N} $1";};bad(){ echo -e "${R}✗${N} $1";};warn(){ echo -e "${Y}!${N} $1";};pause(){ read -r -p 'Press Enter to continue...' _;};root(){ [ "$(id -u)" -eq 0]|| {bad 'Run as root.';exit 1;};}
install_c(){ apt-get update||true;apt-get install -y certbot python3-certbot-nginx;command -v certbot>/dev/null&&ok 'Certbot installed'||bad 'Certbot failed';pause;};generate(){ command -v certbot>/dev/null||install_c;read -r -p 'Enter domain: ' d;[ -n "$d" ]|| {bad 'Domain required';pause;return;};certbot --nginx -d "$d";pause;};renew(){ certbot renew;pause;};status(){ banner;certbot certificates 2>/dev/null||warn 'Certbot not installed or no certificates';pause;};menu(){ root;while true;do banner;echo '[1] Install Certbot';echo '[2] Generate SSL';echo '[3] Renew SSL';echo '[4] Certificate Status';echo '[5] Back';read -r -p 'Select: ' c;case "$c" in 1)install_c;;2)generate;;3)renew;;4)status;;5)return;;*)bad 'Invalid option';;esac;done;};menu
